import xml.etree.ElementTree as ET, os
paths=['coindesk.xml','coindesk_new.xml','cointelegraph.xml','cointelegraph_new.xml','decrypt.xml','decrypt_new.xml','gnews.xml','google.xml','google_news.xml','googlenews.xml','googlenews_new.xml']
for path in paths:
    if not os.path.exists(path):
        continue
    try:
        root=ET.parse(path).getroot()
    except Exception as e:
        print('ERR', path, e)
        continue
    items=root.findall('.//item') or root.findall('.//entry')
    print('\n##', path, 'items', len(items))
    for it in items[:10]:
        title=(it.findtext('title') or '').strip().replace('\n',' ')
        link=(it.findtext('link') or '').strip()
        if not link:
            # atom link href
            for child in it.findall('{http://www.w3.org/2005/Atom}link'):
                link = child.attrib.get('href','')
                if link: break
        print('-', title[:160])
